    def test_init_instance_none_initial_provided(self):
        class MyForm(forms.BaseModelForm):
            class Meta:
                model = Book
                fields = ['title']

        initial_data = {'title': 'Test Book'}
        form = MyForm(initial=initial_data)
        self.assertIsInstance(form.instance, Book)
        self.assertEqual(form.instance.title, '')

    def test_init_instance_provided_initial_none(self):
        book = Book.objects.create(title='Existing Book')
        class MyForm(forms.BaseModelForm):
            class Meta:
                model = Book
                fields = ['title']

