            pass
        monkeypatch.setattr("pytest.Class", type("Class", (object,), {"obj": NotATest}))
        instance = pytest.Class()
        result = instance.collect()
        assert result == []

    def test_collect_with_init(self, monkeypatch):
        class HasInit:
            def __init__(self):
                pass
        monkeypatch.setattr("pytest.Class", type("Class", (object,), {"obj": HasInit}))
        instance = pytest.Class()
        with patch("pytest.Class.warn") as mock_warn:
            result = instance.collect()
            assert result == []
            mock_warn.assert_called_once_with(
                PytestCollectionWarning(
                    "cannot collect test class %r because it has a __init__ constructor"
                    % HasInit.__name__
                )
            )

    def test_collect_with_new(self, monkeypatch):
        class HasNew:
            def __new__(cls):
                return super().__new__(cls)
        monkeypatch.setattr("pytest.Class", type("Class", (object,), {"obj": HasNew}))
        instance = pytest.Class()
        with patch("pytest.Class.warn") as mock_warn:
            result = instance.collect()
            assert result == []
            mock_warn.assert_called_once_with(
                PytestCollectionWarning(
                    "cannot collect test class %r because it has a __new__ constructor"
                    % HasNew.__name__
                )
            )

    def test_collect_valid_class(self, monkeypatch):
        class ValidTest:
            pass
        monkeypatch.setattr("pytest.Class", type("Class", (object,), {"obj": ValidTest}))
        instance = pytest.Class()
        monkeypatch.setattr("pytest.Instance", type("Instance", (object,), {}))
