    def pytest_ignore_collect(self, fspath, config):
        return False

@hookimpl
def pytest_collect_file(fspath, parent):
    if fspath.suffix == ".py":
        return Package.from_parent(parent, path=fspath)
    return None

def _recurse(self, direntry):
    if direntry.name == '__pycache__':
        return False
    fspath = Path(direntry.path)
    ihook = self.session.gethookproxy(fspath.parent)
