class ModelInitTests(SimpleTestCase):

    def test_abstract_model_instantiation(self):
        class AbstractModel(models.Model):
            class Meta:
                abstract = True

        with self.assertRaises(TypeError) as context:
            AbstractModel()
        self.assertEqual(str(context.exception), "Abstract models cannot be instantiated.")

    def test_args_exceed_fields(self):
        class MyModel(models.Model):
            field1 = models.CharField(max_length=10)
            field2 = models.IntegerField()

        with self.assertRaises(IndexError) as context:
            MyModel("value1", 123, "extra")
        self.assertEqual(str(context.exception), "Number of args exceeds number of fields")

    def test_kwargs_only(self):
        class MyModel(models.Model):
            field1 = models.CharField(max_length=10)
            field2 = models.IntegerField()

        instance = MyModel(field1="value1", field2=123)
        self.assertEqual(instance.field1, "value1")
        self.assertEqual(instance.field2, 123)

    def test_args_and_kwargs(self):
        class MyModel(models.Model):
            field1 = models.CharField(max_length=10)
            field2 = models.IntegerField()

        instance = MyModel("value1", 123, field2=456)
        self.assertEqual(instance.field1, "value1")
        self.assertEqual(instance.field2, 123)

    def test_deferred_field(self):
        class MyModel(models.Model):
            field1 = models.CharField(max_length=10)
            field2 = models.IntegerField()

        instance = MyModel("value1", DEFERRED)
        self.assertEqual(instance.field1, "value1")
        self.assertTrue(hasattr(instance, 'field2'))
        self.assertIsNone(getattr(instance, 'field2'))

    def test_related_object_assignment(self):
        class Author(models.Model):
            name = models.CharField(max_length=100)

        class Book(models.Model):
            author = models.ForeignKey(Author, on_delete=models.CASCADE)

        author = Author(name="Test Author")
        author.save()
        book = Book(author=author)
        self.assertEqual(book.author, author)

    def test_related_object_id_assignment(self):
        class Author(models.Model):
            name = models.CharField(max_length=100)

        class Book(models.Model):
            author = models.ForeignKey(Author, on_delete=models.CASCADE)

        author = Author(name="Test Author")
        author.save()
        book = Book(author=author.pk)
        self.assertEqual(book.author, author)
