class TestModelFromDB(TestCase):
    def test_from_db_len_values_not_equal_concrete_fields(self):
        class MyModel(models.Model):
            field1 = models.CharField(max_length=255)
            field2 = models.IntegerField()

        db_values = [1]
        field_names = ['field1']
        instance = MyModel.from_db(using='default', field_names=field_names, values=db_values)
        self.assertEqual(instance.field1, '1')
        self.assertIsNone(instance.field2)

    def test_from_db_len_values_equal_concrete_fields(self):
        class MyModel(models.Model):
            field1 = models.CharField(max_length=255)
            field2 = models.IntegerField()

        db_values = [1, 2]
        field_names = ['field1', 'field2']
        instance = MyModel.from_db(using='default', field_names=field_names, values=db_values)
        self.assertEqual(instance.field1, 1)
        self.assertEqual(instance.field2, 2)
