        parent = Parent.objects.create(grandparent=grandparent)
        child = Child(parent=parent)
        child.save()
        self.assertEqual(Child.objects.get(pk=child.pk).parent, parent)
        self.assertEqual(Child.objects.get(pk=child.pk).parent.grandparent, grandparent)

