    def test_check_local_fields_empty_fields(self):
        class Model(models.Model):
            pass

        self.assertEqual(Model._check_local_fields([], 'test'), [])

    def test_check_local_fields_valid_fields(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=20)
            field2 = models.IntegerField()

        self.assertEqual(Model._check_local_fields(['field1', 'field2'], 'test'), [])

    def test_check_local_fields_invalid_field(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=20)

        errors = Model._check_local_fields(['field1', 'field3'], 'test')
        self.assertEqual(len(errors), 1)
        self.assertIsInstance(errors[0], checks.Error)
        self.assertIn("'%s' refers to the nonexistent field '%s'." % ('test', 'field3'), str(errors[0]))

    def test_check_local_fields_m2m_field(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=20)
            m2m_field = models.ManyToManyField(Model)

        errors = Model._check_local_fields(['field1', 'm2m_field'], 'test')
        self.assertEqual(len(errors), 1)
        self.assertIsInstance(errors[0], checks.Error)
        self.assertIn("'test' refers to a ManyToManyField 'm2m_field', but ManyToManyFields are not permitted in 'test'.", str(errors[0]))

    def test_check_local_fields_non_local_field(self):
        class Parent(models.Model):
            field1 = models.CharField(max_length=20)

        class Child(Parent):
            field2 = models.IntegerField()

        errors = Child._check_local_fields(['field1'], 'test')
        self.assertEqual(len(errors), 1)
        self.assertIsInstance(errors[0], checks.Error)
        self.assertIn("'test' refers to field 'field1' which is not local to model 'Child'.", str(errors[0]))
