            self.assertIn("fabs", namespace)
            self.assertIn("ellipk", namespace)
            self.assertIn("j", namespace)

        def test_import_numpy(self):
            namespace = {}
            _import("numpy", namespace=namespace)
            self.assertIn("heaviside", namespace)
            self.assertIn("j", namespace)

        def test_import_sympy(self):
            namespace = {}
            _import("sympy", namespace=namespace)
            self.assertIn("Integral", namespace)
            self.assertIn("pi", namespace)
            self.assertIn("oo", namespace)

        def test_import_tensorflow(self):
            try:
                import tensorflow as tf
                namespace = {}
                _import("tensorflow", namespace=namespace)
                self.assertIn("constant", namespace)
            except ImportError:
                pass

        def test_import_module_reload(self):
            namespace = {}
            _import("math", namespace=namespace)
            namespace2 = {}
            _import("math", namespace=namespace2, reload=True)
            self.assertEqual(namespace, namespace2)

        def test_import_module_error(self):
            with self.assertRaises(NameError):
                _import("invalid_module")

        def test_import_module_command_error(self):
            with self.assertRaises(ImportError):
                _import("math", import_commands=["invalid_command"])

        def test_import_module_with_import_module(self):
            namespace = {}
            _import("math", import_commands=["import_module('math')"])
            self.assertIn("ceil", namespace)

        def test_import_module_with_exec(self):
            namespace = {}
            _import("math", import_commands=["x = 2"])
            self.assertEqual(namespace.get("x"), 2)

