def test_lambdastr_printer():
    x, y = symbols('x y')
    class MyPrinter:
        def doprint(self, expr):
            return str(expr) + '_printed'
    printer = MyPrinter()
    assert lambdastr(x, x**2, printer=printer) == 'x**2_printed'
    assert lambdastr((x, y), x + y, printer=printer) == '(x + y)_printed'

def test_lambdastr_dummify_none():
    x = symbols('x')
    assert lambdastr(x, x**2, dummify=None) == 'lambda x: (x**2)'

