def test_itermonomials_case_ii():
    """Test case for Case II of itermonomials function."""
    from sympy.abc import x, y
    from sympy.polys.orderings import monomial_key
    assert set(itermonomials([x, y], [2, 4], [1, 2])) == {x, x**2, x*y, y, y**2, x*y**2, y**3, x**2*y, x**2*y**2, x*y**3, y**4, x**2*y**3, x*y**4, x**2*y**4}
    assert set(itermonomials([x, y], [1, 1], [0, 0])) == {x, y}
    assert set(itermonomials([x, y], [1, 1], [1, 1])) == {x, y}
    assert set(itermonomials([x, y], [2, 2], [1, 1])) == {x, x**2, y, y**2, x*y}
    assert set(itermonomials([x, y], [2, 2], [0, 0])) == {1, x, y, x**2, y**2, x*y}
    assert set(itermonomials([x, y], [2, 2], [2, 2])) == set()
    assert set(itermonomials([x, y], [1, 2], [1, 1])) == {x, y, x*y}
    assert set(itermonomials([x, y], [1, 2], [0, 0])) == {1, x, y, x*y}
    assert set(itermonomials([x, y], [1, 2], [0, 1])) == {y, x*y}
    assert set(itermonomials([x, y], [1, 2], [1, 0])) == {x}
    assert set(itermonomials([x, y], [1, 2], [1, 1])) == {x, y}
    assert set(itermonomials([x, y], [2, 4], [1, 2])) == {x, x**2, x*y, y, y**2, x*y**2, y**3, x**2*y, x**2*y**2, x*y**3, y**4, x**2*y**3, x*y**4, x**2*y**4}
    assert set(itermonomials([x, y], [2, 4], [0, 0])) == {1, x, x**2, y, y**2, y**3, y**4, x*y, x*y**2, x*y**3, x*y**4, x**2*y, x**2*y**2, x**2*y**3, x**2*y**4}
    assert set(itermonomials([x, y], [2, 4], [0, 1])) == {y, y**2, y**3, y**4, x*y, x*y**2, x*y**3, x*y**4, x**2*y, x**2*y**2, x**2*y**3, x**2*y**4}
    assert set(itermonomials([x, y], [2, 4], [1, 0])) == {x, x**2, x*y, x**2*y}
    assert set(itermonomials([x, y], [2, 4], [1, 1])) == {x, x**2, y, y**2, x*y}
    assert set(itermonomials([x, y], [2, 4], [2, 2])) == {x**2*y**2, x**2*y**3, x**2*y**4, x*y**3, x*y**4}
    assert set(itermonomials([x, y], [2, 4], [2, 3])) == {x**2*y**3, x**2*y**4, x*y**4}
    assert set(itermonomials([x, y], [2, 4], [3, 3])) == {x**2*y**3, x**2*y**4, x*y**4}
    assert set(itermonomials([x, y], [2, 4], [3, 4])) == {x**2*y**4, x*y**4}
    assert set(itermonomials([x, y], [2, 4], [4, 4])) == set()
    assert set(itermonomials([x, y], [0, 0], [0, 0])) == {1}
    assert set(itermonomials([x, y], [0, 0], [1, 1])) == set()
    assert set(itermonomials([x, y], [1, 1], [0, 0])) == {x, y}
    assert set(itermonomials([x, y], [1, 1], [1, 1])) == {x, y}
    assert set(itermonomials([x, y], [1, 1], [2, 2])) == set()
