@pytest.mark.sphinx('dummy', freshenv=True)
def test_create_index_coverage(app):
    """
    Test case to cover various execution paths in IndexEntries.create_index.
    """
    text = (
        ".. index:: docutils\n"
        ".. index:: Python\n"
        ".. index:: pip; install\n"
        ".. index:: pair: Sphinx; documentation tool\n"
        ".. index:: triple: foo; bar; baz\n"
        ".. index:: see: docutils; reStructuredText\n"
        ".. index:: seealso: Python; interpreter\n"
        ".. index:: single: test_single\n"
        ".. index:: single: test_single_one\n"
        ".. index:: !test_main\n"
        ".. index:: test_main\n"
    )
    restructuredtext.parse(app, text)
    index = IndexEntries(app.env).create_index(app.builder)

    assert len(index) > 0

    # Check for 'single' index entries
    found_single_docutils = False
    found_single_python = False
    found_single_test_single = False
    found_single_test_single_one = False
    for entry in index:
        if entry[0] == 'D':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'docutils':
                    found_single_docutils = True
        if entry[0] == 'P':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'Python':
                    found_single_python = True
        if entry[0] == 't':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'test_single':
                    found_single_test_single = True
        if entry[0] == 't':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'test_single_one':
                    found_single_test_single_one = True

    assert found_single_docutils
    assert found_single_python
    assert found_single_test_single
    assert found_single_test_single_one

    # Check for 'pair' index entries
    found_pair = False
    for entry in index:
        if entry[0] == 'S':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'Sphinx':
                    found_pair = True
                    break
    assert found_pair

    # Check for 'triple' index entries
    found_triple = False
    for entry in index:
        if entry[0] == 'f':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'foo':
                    found_triple = True
                    break
    assert found_triple

    # Check for 'see' index entries
    found_see = False
    for entry in index:
        if entry[0] == 'D':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'docutils':
                    found_see = True
                    break
    assert found_see

    # Check for 'seealso' index entries
    found_seealso = False
    for entry in index:
        if entry[0] == 'P':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'Python':
                    found_seealso = True
                    break
    assert found_seealso

    # Check for main index entries
    found_main = False
    for entry in index:
        if entry[0] == 't':
            for sub_entry in entry[1]:
                if sub_entry[0] == 'test_main':
                    found_main = True
                    break
    assert found_main
