import pytest

from sklearn.utils._set_output import _SetOutputMixin


def test_init_subclass_invalid_auto_wrap_output_keys():
    """Check that invalid auto_wrap_output_keys raises ValueError."""
    with pytest.raises(ValueError, match="auto_wrap_output_keys must be None or a tuple of keys."):

        class BadEstimator(_SetOutputMixin, auto_wrap_output_keys="bad_parameter"):
            pass


def test_init_subclass_auto_wrap_output_keys_none():
    """Check that auto_wrap_output_keys=None sets _sklearn_auto_wrap_output_keys to set()."""

    class MyEstimator(_SetOutputMixin, auto_wrap_output_keys=None):
        pass

    assert MyEstimator._sklearn_auto_wrap_output_keys == set()


def test_init_subclass_auto_wrap_output_keys_tuple():
    """Check that auto_wrap_output_keys=tuple works as expected."""

    class MyEstimator(_SetOutputMixin, auto_wrap_output_keys=("transform", "fit_transform")):
        def transform(self, X, y=None):
            return X

        def fit_transform(self, X, y=None):
            return X

    assert MyEstimator._sklearn_auto_wrap_output_keys == {"transform", "fit_transform"}


def test_init_subclass_auto_wrap_output_keys_tuple_with_missing_method():
    """Check that auto_wrap_output_keys=tuple handles missing methods."""

    class MyEstimator(_SetOutputMixin, auto_wrap_output_keys=("transform", "missing_method")):
        def transform(self, X, y=None):
            return X

    assert MyEstimator._sklearn_auto_wrap_output_keys == {"transform"}


def test_init_subclass_auto_wrap_output_keys_tuple_with_method_not_in_dict():
    """Check that auto_wrap_output_keys=tuple handles methods not defined in the class."""

    class MyEstimator(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
