        with self.settings(TEMPLATES=[{
            "BACKEND": "django.template.backends.django.DjangoTemplates",
            "OPTIONS": {
                "libraries": {"test_lib": "test_app.templatetags.test_lib"},
            },
        }]):
            self.assertEqual(check_for_template_tags_with_the_same_name(None), [])

    def test_multiple_libraries_defined_no_conflict(self):
        with self.settings(TEMPLATES=[{
            "BACKEND": "django.template.backends.django.DjangoTemplates",
            "OPTIONS": {
                "libraries": {
                    "lib1": "app1.templatetags.lib1",
                    "lib2": "app2.templatetags.lib2",
                },
            },
        }]):
