def test_canonical_variables():
    from sympy import Lambda, symbols
    x, y, z = symbols('x y z')

    # Path 1: No bound symbols
    assert Basic().canonical_variables == {}

    # Path 2-7: With bound symbols
    assert Lambda(x, 2*x).canonical_variables == {x: symbols('_0')}
    assert Lambda(x, x + 1).canonical_variables == {x: symbols('_0')}
    assert Lambda(x, x**2).canonical_variables == {x: symbols('_0')}
    assert Lambda(x, 2*x + y).canonical_variables == {x: symbols('_0'), y: symbols('_1')}
    assert Lambda(x, x + y + z).canonical_variables == {x: symbols('_0'), y: symbols('_1'), z: symbols('_2')}

    # Test with existing symbols
    a, b = symbols('a b')
    assert Lambda(a, 2*a).canonical_variables == {a: symbols('_0')}
    assert Lambda(a, a + b).canonical_variables == {a: symbols('_0'), b: symbols('_1')}

    # Test with clashing names
    x = symbols('x')
    assert Integral(x, (x, 0, 1)).canonical_variables == {x: symbols('_0')}
    assert Integral(x, (x, 0, x)).canonical_variables == {x: symbols('_0')}
